<span class="line">      <span class="token keyword">return</span> <span class="token function">cb</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Error</span><span class="token punctuation">(</span><span class="token string">&#39;不支持的文件类型&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
